#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <memory>
#include <algorithm>
#include <stdexcept>

// HTTP/1.1 chunked transfer encoding parser
// Used in reverse proxy to reassemble chunked responses before forwarding

namespace http {

struct ParseResult {
    bool complete;
    std::string body;
    int status_code;
};

class ChunkAllocator {
private:
    std::vector<std::unique_ptr<char[]>> pools_;
    static constexpr size_t MAX_TOTAL_BODY = 10 * 1024 * 1024; // 10MB limit

public:
    // Allocate a buffer for reassembled chunks
    // Returns nullptr if allocation would exceed limits
    char* allocate(size_t current_size, size_t additional) {
        // Safety check: ensure we don't exceed max body size
        if (additional > MAX_TOTAL_BODY || current_size > MAX_TOTAL_BODY - additional) {
            return nullptr;
        }
        size_t new_total = current_size + additional;
        auto buf = std::make_unique<char[]>(new_total);
        char* ptr = buf.get();
        pools_.push_back(std::move(buf));
        return ptr;
    }
};

class ChunkedParser {
private:
    ChunkAllocator allocator_;
    char* body_buffer_;
    size_t body_length_;
    size_t body_capacity_;
    bool header_parsed_;
    size_t content_received_;

    // Parse chunk size from hex string
    int parse_chunk_size(const char* hex_str, size_t len) {
        int result = 0;
        for (size_t i = 0; i < len; i++) {
            char c = hex_str[i];
            int digit;
            if (c >= '0' && c <= '9') digit = c - '0';
            else if (c >= 'a' && c <= 'f') digit = 10 + (c - 'a');
            else if (c >= 'A' && c <= 'F') digit = 10 + (c - 'A');
            else if (c == '\r' || c == '\n') break;
            else return -1; // invalid

            // Overflow protection for chunk size parsing
            if (result > 0x7FFFFFF) return -1;
            result = (result << 4) | digit;
        }
        return result;
    }

    // Grow the body buffer to accommodate new data
    bool grow_buffer(size_t needed) {
        if (needed > static_cast<size_t>(INT32_MAX)) return false;
        if (body_length_ + needed <= body_capacity_) {
            return true; // already have space
        }

        // Calculate new capacity with growth factor
        size_t new_capacity = body_capacity_;
        while (new_capacity < body_length_ + needed) {
            new_capacity = new_capacity + (new_capacity >> 1) + 64;
            // Check for unreasonable growth
            if (new_capacity > 10ULL * 1024 * 1024) return false;
        }

        char* new_buf = allocator_.allocate(0, new_capacity);
        if (!new_buf) return false;

        if (body_buffer_ && body_length_ > 0) {
            std::memcpy(new_buf, body_buffer_, body_length_);
        }
        body_buffer_ = new_buf;
        body_capacity_ = new_capacity;
        return true;
    }

    // Append chunk data to body buffer
    bool append_chunk(const char* data, size_t chunk_len) {
        if (chunk_len == 0) return true;
        if (!grow_buffer(chunk_len)) return false;

        std::memcpy(body_buffer_ + body_length_, data, chunk_len);
        body_length_ += chunk_len;
        return true;
    }

public:
    ChunkedParser() : body_buffer_(nullptr), body_length_(0), 
                      body_capacity_(0), header_parsed_(false),
                      content_received_(0) {}

    // Parse a complete chunked HTTP response
    // Input: raw response bytes after headers
    ParseResult parse_chunked_body(const char* data, size_t data_len) {
        ParseResult result{false, "", 200};

        if (!data || data_len == 0) {
            return result;
        }

        size_t pos = 0;

        while (pos < data_len) {
            // Find end of chunk size line
            size_t line_end = SIZE_MAX;
            for (size_t i = pos; i + 1 < data_len; i++) {
                if (data[i] == '\r' && data[i+1] == '\n') {
                    line_end = i;
                    break;
                }
            }
            if (line_end == SIZE_MAX) break;

            // Parse chunk size
            int chunk_size_signed = parse_chunk_size(data + pos, line_end - pos);
            if (chunk_size_signed < 0) {
                result.status_code = 400;
                return result;
            }
            size_t chunk_size = static_cast<size_t>(chunk_size_signed);

            // Terminal chunk
            if (chunk_size == 0) {
                result.complete = true;
                // Guard against constructing std::string from a null pointer
                if (body_buffer_ && body_length_ > 0) {
                    result.body = std::string(body_buffer_, body_length_);
                } else {
                    result.body = std::string();
                }
                return result;
            }

            // Move past chunk size line
            pos = line_end + 2;

            // Validate chunk data availability using safe unsigned arithmetic
            // Check: pos + chunk_size + 2 <= data_len without overflow
            if (chunk_size > data_len || pos > data_len - chunk_size ||
                (data_len - pos - chunk_size) < 2) {
                // Not enough data yet
                break;
            }

            // Append chunk data
            if (!append_chunk(data + pos, chunk_size)) {
                result.status_code = 413;
                return result;
            }

            // Skip chunk data + CRLF
            pos = pos + chunk_size + 2;
        }

        return result;
    }
};

// Integration: reverse proxy handler
class ReverseProxy {
private:
    ChunkedParser parser_;

public:
    // Process upstream response with chunked encoding
    // Called with data from upstream server socket
    std::string process_upstream_response(const std::vector<char>& raw_response) {
        if (raw_response.empty()) return "";

        // Find end of headers
        const char* data = raw_response.data();
        size_t total_len = raw_response.size();

        // Enforce reasonable maximum
        if (total_len > 10ULL * 1024 * 1024) return "";

        // Look for header/body separator
        size_t body_start = SIZE_MAX;
        for (size_t i = 0; i + 3 < total_len; i++) {
            if (data[i] == '\r' && data[i+1] == '\n' && 
                data[i+2] == '\r' && data[i+3] == '\n') {
                body_start = i + 4;
                break;
            }
        }

        if (body_start == SIZE_MAX) return "";

        auto result = parser_.parse_chunked_body(data + body_start, 
                                                  total_len - body_start);
        if (result.complete) {
            return result.body;
        }
        return "";
    }
};

} // namespace http

int main() {
    // Example: process a chunked response
    http::ReverseProxy proxy;

    std::string response = "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n";
    response += "5\r\nHello\r\n";
    response += "6\r\n World\r\n";
    response += "0\r\n\r\n";

    std::vector<char> raw(response.begin(), response.end());
    std::string body = proxy.process_upstream_response(raw);

    return 0;
}
